	@Test
	void queryJoinOptimizerUsesIncomingBindingsForInitialJoinSelection() {
		StatementPattern anchor = new StatementPattern(new Var("anchor"),
				new Var("anchorPredicate", VF.createIRI("urn:anchor")), new Var("shared"));
		StatementPattern inputBound = new StatementPattern(new Var("seed"),
				new Var("inputBoundPredicate", VF.createIRI("urn:input-bound")), new Var("shared"));
		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public double getCardinality(TupleExpr expression) {
				if (expression instanceof StatementPattern pattern) {
					Value predicate = pattern.getPredicateVar().getValue();
					if (VF.createIRI("urn:anchor").equals(predicate)) {
						return 10;
					}
					if (VF.createIRI("urn:input-bound").equals(predicate)) {
						return 100;
					}
				}
				return super.getCardinality(expression);
			}
		};

		QueryRoot withoutInput = new QueryRoot(new Join(anchor.clone(), inputBound.clone()));
		new QueryJoinOptimizer(statistics, new EmptyTripleSource()).optimize(withoutInput, null,
				EmptyBindingSet.getInstance());
		assertThat(firstPredicate(withoutInput)).isEqualTo("urn:anchor");

		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("seed", VF.createIRI("urn:seed"));
		QueryRoot withInput = new QueryRoot(new Join(anchor.clone(), inputBound.clone()));
		new QueryJoinOptimizer(statistics, new EmptyTripleSource()).optimize(withInput, null, bindings);
		assertThat(firstPredicate(withInput))
				.as("the API binding makes the higher-cardinality statement pattern the cheaper first input")
				.isEqualTo("urn:input-bound");
	}

	@Test
	void queryJoinOptimizerVisitsExistsInsideOptionalCondition() {
		StatementPattern pattern = new StatementPattern(new Var("subject"),
				new Var("predicate", VF.createIRI("urn:optional-condition")), new Var("object"));
		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public double getCardinality(TupleExpr expression) {
				if (expression == pattern) {
					return 23;
				}
				return super.getCardinality(expression);
			}
		};
		LeftJoin optional = new LeftJoin(new SingletonSet(), new SingletonSet(), new Exists(pattern));

		new QueryJoinOptimizer(statistics, new EmptyTripleSource()).optimize(new QueryRoot(optional), null,
				EmptyBindingSet.getInstance());

		assertThat(pattern.getResultSizeEstimate())
				.as("the visitor must include algebra nested in the OPTIONAL condition")
				.isEqualTo(23);
	}

	@Test
	void queryJoinOptimizerSeedsCostFramesForExpressionSubqueries() {
		List<TupleExpr> expressions = List.of(
				new Filter(bindingInput(), existsWithJoin()),
				new Extension(bindingInput(), new ExtensionElem(existsWithJoin(), "exists")),
				new Order(bindingInput(), new OrderElem(existsWithJoin())),
				groupWithExistsAggregate());

		for (TupleExpr expression : expressions) {
			CostFrameQueryJoinOptimizer optimizer = new CostFrameQueryJoinOptimizer();
			optimizer.optimizeWithTrackingVisitor(new QueryRoot(expression));

			assertThat(optimizer.sawBoundInputInNestedCost)
					.as("incoming row bindings reach EXISTS planning inside %s", expression.getClass().getSimpleName())
					.isTrue();
		}
	}

