	private static String firstPredicate(QueryRoot root) {
		List<StatementPattern> patterns = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				patterns.add(pattern);
			}
		});
		return patterns.getFirst().getPredicateVar().getValue().stringValue();
	}

	private static TupleExpr bindingInput() {
		return new StatementPattern(Var.of("s"), new Var("outerPredicate", VF.createIRI("urn:outer")),
				Var.of("outerObject"));
	}

	private static BindingSetAssignment values(String name, Value value) {
		BindingSetAssignment values = new BindingSetAssignment();
		MapBindingSet row = new MapBindingSet();
		row.addBinding(name, value);
		values.setBindingSets(List.of(row));
		return values;
	}

	private static Exists existsWithJoin() {
		StatementPattern first = new StatementPattern(Var.of("s"), new Var("firstPredicate", VF.createIRI("urn:first")),
				Var.of("middle"));
		StatementPattern second = new StatementPattern(Var.of("middle"),
				new Var("secondPredicate", VF.createIRI("urn:second")), Var.of("end"));
		return new Exists(new Join(first, second));
	}

	private static TupleExpr groupWithExistsAggregate() {
		Group group = new Group(bindingInput());
		group.addGroupElement(new GroupElem("count", new Count(existsWithJoin())));
		return group;
	}

	private static List<BindingSet> evaluate(TupleExpr expression, BindingSet bindings) throws Exception {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, bindings)) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		return results;
	}

	private static final class CostFrameQueryJoinOptimizer extends QueryJoinOptimizer {
		private boolean sawBoundInputInNestedCost;

		private CostFrameQueryJoinOptimizer() {
			super(new EvaluationStatistics(), new EmptyTripleSource());
		}

		private void optimizeWithTrackingVisitor(TupleExpr expression) {
			expression.visit(new CostFrameJoinVisitor());
		}

		private class CostFrameJoinVisitor extends JoinVisitor {
			@Override
			protected List<Var> getUnboundVars(List<Var> vars) {
				List<Var> unbound = super.getUnboundVars(vars);
				boolean usesInputName = vars.stream().anyMatch(var -> "s".equals(var.getName()));
				boolean inputNameIsUnbound = unbound.stream().anyMatch(var -> "s".equals(var.getName()));
				sawBoundInputInNestedCost |= usesInputName && !inputNameIsUnbound;
				return unbound;
			}
		}
	}

	/**
	 * ConstantOptimizer only folds BOUND for constants (join reordering can move the expression away from the frame it
	 * was analysed in), so frame selection is asserted on the shared analysis directly.
	 */
	private static boolean isGuaranteedAtBound(TupleExpr root, Bound bound) {
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(root,
				EmptyBindingSet.getInstance());
		return analysis.expressionIsGuaranteed(bound.getArg(), analysis.contextAt(bound));
	}

	private static List<Bound> collectBounds(TupleExpr expression) {
		List<Bound> bounds = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Bound bound) {
				bounds.add(bound);
				super.meet(bound);
			}
		});
		return bounds;
	}
